-- Seed the PASSWORD_RESET template used by Identity's self-service forgot-password flow
-- (Modules/Identity/UseCases/PasswordResetUseCase.cs calls IEmailService.SendAsync with this Code).
IF NOT EXISTS (SELECT 1 FROM Setting_EmailTemplates WHERE Code = 'PASSWORD_RESET')
BEGIN
    INSERT INTO Setting_EmailTemplates
        (Code, Name, Description, FromEmail, FromName, IsReplyToEnabled, Subject, BodyHtml, BodyText, AvailablePlaceholders, IsActive)
    VALUES
        (
            'PASSWORD_RESET',
            'Password Reset',
            'Sent when a user requests a password reset from the login page.',
            'no-reply@sugentra.local',
            'Sugentra ERP',
            0,
            'Reset Your Password',
            '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background-color:#f4f6f8;padding:40px 0;font-family:Arial,Helvetica,sans-serif;"><tr><td align="center"><table role="presentation" width="480" cellpadding="0" cellspacing="0" style="background-color:#ffffff;border-radius:8px;overflow:hidden;border:1px solid #e5e7eb;"><tr><td align="center" style="background-color:#0d9394;padding:28px 24px;"><img src="data:image/png;base64," alt="Sugentra ERP" style="height:32px;display:block;" /></td></tr><tr><td style="padding:32px 32px 8px 32px;color:#1f2937;font-size:15px;line-height:1.6;"><p style="margin:0 0 16px 0;">Hello {{FullName}},</p><p style="margin:0 0 16px 0;">We received a request to reset the password for your account. Use the verification code below, or click the button to continue.</p></td></tr><tr><td align="center" style="padding:8px 32px 24px 32px;"><div style="display:inline-block;background-color:#f0fbfb;border:1px dashed #0d9394;border-radius:8px;padding:16px 32px;"><span style="font-size:28px;font-weight:700;letter-spacing:6px;color:#0d9394;">{{Code}}</span></div></td></tr><tr><td align="center" style="padding:0 32px 24px 32px;"><a href="{{ResetLink}}" rel="noopener noreferrer" target="_blank" style="background-color:#0d9394;color:#ffffff;text-decoration:none;font-weight:600;font-size:14px;padding:12px 32px;border-radius:6px;display:inline-block;">Reset Password</a></td></tr><tr><td style="padding:0 32px 32px 32px;color:#6b7280;font-size:13px;line-height:1.6;border-top:1px solid #e5e7eb;padding-top:20px;"><p style="margin:0;">This code expires in {{ExpiresMinutes}} minutes. If you did not request this, you can safely ignore this email — your password will remain unchanged.</p></td></tr></table><table role="presentation" width="480" cellpadding="0" cellspacing="0" style="margin-top:16px;"><tr><td align="center" style="color:#9ca3af;font-size:12px;font-family:Arial,Helvetica,sans-serif;">This is an automated message from Sugentra ERP. Please do not reply to this email.</td></tr></table></td></tr></table>',
            'Hello {{FullName}}, your password reset code is {{Code}} (expires in {{ExpiresMinutes}} minutes). Reset link: {{ResetLink}}',
            'FullName,Code,ResetLink,ExpiresMinutes',
            1
        );
END
